<?php require '../../includes/config.php';require '../../includes/layout.php';require_login(['student']);$uid=$_SESSION['user']['id'];$total=$conn->query("SELECT COUNT(*) c FROM tickets WHERE student_id=$uid")->fetch_assoc()['c'];$open=$conn->query("SELECT COUNT(*) c FROM tickets WHERE student_id=$uid AND status IN ('Submitted','In Progress')")->fetch_assoc()['c'];$resolved=$conn->query("SELECT COUNT(*) c FROM tickets WHERE student_id=$uid AND status='Resolved'")->fetch_assoc()['c'];$closed=$conn->query("SELECT COUNT(*) c FROM tickets WHERE student_id=$uid AND status='Closed'")->fetch_assoc()['c'];student_shell('Student Dashboard','dashboard');?><div class="page-header"><h2>Welcome, <?=e($_SESSION['user']['name'])?></h2><p>Manage your complaints and support requests.</p></div><div class="stat-grid"><div class="stat"><strong><?=$total?></strong>Total Tickets</div><div class="stat"><strong><?=$open?></strong>Open Tickets</div><div class="stat"><strong><?=$resolved?></strong>Resolved</div><div class="stat"><strong><?=$closed?></strong>Closed</div></div><div class="content-card"><h3>Quick Action</h3><p>Need help or want to report an issue? Submit a new complaint ticket.</p><a class="btn btn-primary" href="new-ticket.php">Submit a Complaint</a></div><?php dashboard_footer(); ?>